xpath.script:
document.addEventListener('DOMContentLoaded', function() {
    initTimesheetCheckboxListeners();
});

function initTimesheetCheckboxListeners() {
    var selectAllCb = document.getElementById('ts_select_all_cb');
    if (selectAllCb) {
        selectAllCb.addEventListener('change', function() {
            var rowCbs = document.querySelectorAll('.ts-row-cb');
            var groupCbs = document.querySelectorAll('.ts-group-cb');
            for (var i = 0; i < rowCbs.length; i++) {
                rowCbs[i].checked = this.checked;
            }
            for (var j = 0; j < groupCbs.length; j++) {
                groupCbs[j].checked = this.checked;
            }
            updateTsExportSelectionCount();
        });
    }
}

function toggleTsGroupSelection(groupCb) {
    var groupTarget = groupCb.getAttribute('data-group-target');
    if (groupTarget) {
        // Find all child rows matching group target class
        var childRows = document.querySelectorAll('.' + groupTarget);
        for (var i = 0; i < childRows.length; i++) {
            var row = childRows[i];
            var cb = row.querySelector('.ts-row-cb');
            if (cb) {
                cb.checked = groupCb.checked;
            }
            var nestedGrpCb = row.querySelector('.ts-group-cb');
            if (nestedGrpCb) {
                nestedGrpCb.checked = groupCb.checked;
            }
        }
    }
    updateTsExportSelectionCount();
}

function updateTsExportSelectionCount() {
    var checkedCbs = document.querySelectorAll('.ts-row-cb:checked');
    var badge = document.getElementById('ts_selected_badge');
    if (badge) {
        if (checkedCbs.length > 0) {
            badge.textContent = checkedCbs.length + ' selected';
            badge.classList.remove('d-none');
        } else {
            badge.classList.add('d-none');
        }
    }
}

function handleTimesheetExcelExport() {
    var checkedCbs = document.querySelectorAll('.ts-row-cb:checked');
    var selectedIds = [];
    for (var i = 0; i < checkedCbs.length; i++) {
        selectedIds.push(checkedCbs[i].value);
    }

    var currentUrl = new URL(window.location.href);
    var exportUrl = new URL('/my/timesheets/export', window.location.origin);

    // Preserve current active filters
    if (currentUrl.searchParams.has('scope')) exportUrl.searchParams.set('scope', currentUrl.searchParams.get('scope'));
    if (currentUrl.searchParams.has('groupby')) exportUrl.searchParams.set('groupby', currentUrl.searchParams.get('groupby'));
    if (currentUrl.searchParams.has('filterby')) exportUrl.searchParams.set('filterby', currentUrl.searchParams.get('filterby'));
    if (currentUrl.searchParams.has('search')) exportUrl.searchParams.set('search', currentUrl.searchParams.get('search'));

    // Append selected IDs if any checkboxes are checked
    if (selectedIds.length > 0) {
        exportUrl.searchParams.set('timesheet_ids', selectedIds.join(','));
    }

    window.location.href = exportUrl.href;
}
